// === Tab: tab2 ===
class ball{
spd, pos, acc;
size,sx,sy, dyst;
start, sas, cz_sas;
col;


  constructor(){
		start = 1;
		sx = 0;
		sy = 0;
		dyst = 200;
    spd = new PVector(0,0);
    size = 10;
    pos = new PVector(25,50-size/2);
    acc = new PVector(0,0);
		col = color(255,255,255);
  }

  function reset(){
    pos.x = 25;
    pos.y = 50-size/2;
    spd.x = 1;
    spd.y = 0;
    start = 1;
  }

  function draw(){
    fill(col);
    stroke(col);
    ellipse(pos.x,pos.y,size,size);
  }

  function jump(){
    if (this.pos.x <= 405){
      if (this.pos.x <= 50){
        this.spd.x = 1;
      }
      else if(this.pos.x <= 300){
        if (this.pos.x == 51){
          this.spd.x = 0;
        }
        this.spd.x += g;
        this.spd.y += g;
        this.sx = spd.x;
        this.sy = spd.y;
      }
      this.pos.add(this.spd);
      if (this.pos.x > 300){
        if (this.pos.x <= 315){
          this.pos.y = (this.pos.x - 300) * 0.8 + 300 - this.size/2;
          this.spd.x = 1.2 * sx;
          this.spd.y = 0.8 * sy;
        }
        else if (this.pos.x <= 330){
          this.pos.y = (this.pos.x - 315) * 0.6 + 312 - this.size/2;
          this.spd.x = 1.4 * sx;
          this.spd.y = 0.6 * sy;
        }
        else if (this.pos.x <= 345){
          this.pos.y = (this.pos.x - 330) * 0.4 + 321 - this.size/2;
          this.spd.x = 1.6 * sx;
          this.spd.y = 0.4 * sy;
        }
        else if (this.pos.x <= 360){
          this.pos.y = (this.pos.x - 345) * 0.2 + 327 - this.size/2;
          this.spd.x = 1.8 * sx;
          this.spd.y = 0.2 * sy;
        }
        else if (this.pos.x <= 375){
          this.pos.y = (this.pos.x - 360) * 0 + 330 - this.size/2;
          this.spd.x = 2 * sx;
          this.spd.y = 0 * sy;
        }
        else if (this.pos.x <= 390){
          this.pos.y = (this.pos.x - 390) * 0.4 + 330 - this.size/2;
          this.spd.x = 1.8 * sx;
          this.spd.y = -0.2 * sy;
        }
        else if (this.pos.x <= 405){
          this.pos.y = (this.pos.x - 405) * 0.6 + 327 - this.size/2;
          this.spd.x = 1.4 * sx;
          this.spd.y = 0.6 * sy;
        }
        else{
          start = 0 ;
          this.pos.y = (405 - this.pos.x) * 0.6 + 318;
          this.spd.x = 1.6 * sx;
          this.spd.y = -0.8 * sy;
        }
      }
    }
  }

  function update(){
    this.cz_sas = 0;
    this.dyst = 255;
		print(gravity.size);
    if (gravity.size()>0){
      for (i = 0; i < gravity.size(); i++){
        grav gr = (grav) gravity.get(i);
        let d = PVector.dist(this.pos,gr.pos);
        if (d < dyst){
          this.dyst = d;
          this.sas = i;
          this.cz_sas = 1;
					col = color(d,0,255-d);
        }
      }
    }
    if (this.cz_sas > 0){
    	grav gr = (grav) gravity.get(this.sas);
  	  var d = PVector.dist(this.pos,gr.pos);
	    if (d < (this.size+gr.size)/2){
      	this.spd.x = -this.spd.x;
    	  this.spd.y = -this.spd.y;
  	  }
	    else {
    	  let attraction = new PVector(gr.pos.x, gr.pos.y);
  	    attraction.sub(this.pos);
	      this.acc.set(attraction);
      	this.acc.normalize();
    	  this.acc.div(turnFactor);
  	    this.spd.add(this.acc);
	      this.spd.limit(max_spd * (1/40));
	    }
    	this.pos.add(this.spd);
    }
    else{
      this.spd.y += g;
      this.pos.add(this.spd);
    }
  }
}

