class grav{
pos;
size;

  constructor(x, y){
    pos = new PVector(x,y);
    size = 5;
  }

  function draw(){
    fill(255,0,0);
    ellipse(pos.x,pos.y,size,size);
  }

  move(x, y){
    let xy = new PVector(x,y);
    var d = pos.dist(xy);
    var ch = 0;
    if (d < size/2){
      pos.x = x;
      pos.y = y;
      ch = 1;
    }
    return ch;
  }
}

